syntax:
template <typename T>
ReturnType functionName(T param);

// General template

template <typename T>
ReturnType functionName(T param) {
    // generic implementation
}

// Full specialization for a specific type

template <> 
ReturnType functionName<int>(int param) {
    // specialized implementation for int
}

// Partial specialization is not allowed for function templates, but can be simulated via SFINAE or tag dispatching.

code_example:
#include <iostream>

template<typename Sseq>
void seed(Sseq& q) {
    std::cout << "Generic seed called" << std::endl;
}

// Specialization for std::vector<int>
template<>
void seed(std::vector<int>& q) {
    std::cout << "Specialized seed for vector<int>" << std::endl;
    // Custom behavior for vector<int>
}

int main() {
    std::vector<int> vec = {1, 2, 3};
    seed(vec); // Calls specialized version
    std::list<double> lst = {1.1, 2.2};
    seed(lst); // Calls generic version
    return 0;
}
